  anim('trap', 'opacity', [[0.62 * d, 0], [0.7 * d, 1]], 'ease_out');

  tagChip('research', 'HƯỚNG NGHIÊN CỨU · CHƯA PHẢI LỜI HỨA', 120, 836, C.amber, 11);
  ['researchBg', 'researchT'].forEach((id) => anim(id, 'opacity', [[0.8 * d, 0], [0.86 * d, 1]], 'ease_out'));

  return finish({
