    anim(`w${i}`, 'opacity', [[0.65 * d + i * 0.03 * d, 0], [0.7 * d + i * 0.03 * d, 1]], 'ease_out');
    anim(`w${i}T`, 'opacity', [[0.65 * d + i * 0.03 * d, 0], [0.7 * d + i * 0.03 * d, 1]], 'ease_out');
  }

  return finish({
    name: 'Cái bẫy provider',
