  anim('gTitle', 'opacity', [[0.5 * d, 0], [0.58 * d, 1]], 'ease_out');
  anim('gLine', 'opacity', [[0.5 * d, 0], [0.58 * d, 1]], 'ease_out');
  anim('gFoot', 'opacity', [[0.66 * d, 0], [0.72 * d, 1]], 'ease_out');

