  tagChip('pOk', 'SẴN SÀNG REVIEW', P.x + P.w - 210, P.y + 386, C.green, 10);
  ['pOkBg', 'pOkT'].forEach((id) => anim(id, 'opacity', [[0.86 * d, 0], [0.92 * d, 1]], 'ease_out'));

