    const t0 = 0.66 * d + i * 0.04 * d;
    anim(`cue${i}`, 'opacity', [[t0, 0], [t0 + 0.05 * d, 1]], 'ease_out');
    anim(`cue${i}Top`, 'opacity', [[t0, 0], [t0 + 0.05 * d, 1]], 'ease_out');
    anim(`cue${i}T`, 'opacity', [[t0, 0], [t0 + 0.05 * d, 1]], 'ease_out');
