  tagChip('editTag', 'SỬA TỪNG CHỮ · TỪNG MỐC THỜI GIAN', T.x, T.y + 216, C.cyan, 11);
  ['editTagBg', 'editTagT'].forEach((id) => anim(id, 'opacity', [[0.78 * d, 0], [0.84 * d, 1]], 'ease_out'));

  return finish({
