  ell('mB_glow', V.x + 60, V.y + 150, 460, 220, A(C.cyan, 10));
  for (let i = 0; i < 9; i += 1) {
    const h = 90 + ((i * 53) % 150);
    rect(`mB_t${i}`, V.x + 10 + i * 62, V.y + V.h - h - 24, 48, h, { red: 14, green: 20, blue: 28, alpha: 255 });
    rect(`mB_tc${i}`, V.x + 10 + i * 62, V.y + V.h - h - 24, 48, 2, A(C.cyan, 70));
