    anim(`whisR${i}`, 'opacity', [[T_W + i * 0.25, 0], [T_W + 0.4 + i * 0.25, 1], [T_W + 0.9 + i * 0.25, 0]], 'ease_out');
  }
  txt('whisLabel', 'WHISPER', 1090, 660, 14, A(C.violet, 235));
